begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table selected_text(item uuid,revision uuid,new_revision uuid,evidence uuid);grant select,insert,update on selected_text to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99210000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Selected text source','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','99220000-0000-4000-8000-000000000001','99210000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Text source task','Explain',10,'61000000-0000-4000-8000-000000000001');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','99230000-0000-4000-8000-000000000001','99220000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Exact selected answer. الإجابة الأصلية. <script>plain source</script>');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare result uuid;begin result:=internal.release_marking(internal.mark_submission('99230000-0000-4000-8000-000000000001',6,'Teacher checked the answer',1,0,true),1,true);insert into selected_text(evidence)select evidence_id from app.result_revisions where id=result;end$$;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update selected_text set(item,revision)=((internal.portfolio_command('create',null,jsonb_build_object('sourceModel','numeric','evidenceId',evidence,'title','Selected explanation','reflection','First reflection'),'selected-text-create',repeat('a',64),'selected-text')->>'id')::uuid,null);
reset role;update selected_text set revision=(select revision_id from app.portfolio_current where item_id=selected_text.item);set local role cuevo_api;
select is(internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))->'source'->>'content','Exact selected answer. الإجابة الأصلية. <script>plain source</script>','student source work preserves exact text without markup interpretation');
select is(internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))->'source'->>'submissionRevision','1','text source carries its immutable submitted revision');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'42501',null,'peer cannot obtain another learner selected answer');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'42501',null,'coordinator metadata access does not grant raw answer disclosure');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'42501',null,'parent cannot read unreviewed selected answer');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'current authorized teacher reviews exact source');
select throws_ok($$select internal.portfolio_command('review',(select item from selected_text),'{"expectedRevision":1,"feedback":"Review","featured":false,"parentVisible":true,"confirmParentApproval":true}','selected-text-no-confirm',repeat('b',64),'selected-text')$$,'22023',null,'TEXT review cannot skip explicit submitted source confirmation');
select internal.portfolio_command('review',(select item from selected_text),'{"expectedRevision":1,"feedback":"Exact source reviewed","featured":false,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','selected-text-review',repeat('c',64),'selected-text')is not null as reviewed;
select is((internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))->>'learnerName'),'Lina Al-Kuwari','source review resolves narrow authorized learner name');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))->'source'->>'submissionId','99230000-0000-4000-8000-000000000001','parent approved item exposes only its exact evidence-linked submitted source');
select is((select item->>'sourceWorkApproved'from jsonb_array_elements(internal.read_portfolio_page(100,null,null,null)->'items')item where item->>'id'=(select item::text from selected_text)),'true','list metadata records exact submitted-text review');
select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),'61000000-0000-4000-8000-000000000001')$$,'42501',null,'revision substitution denied');
select ok(not has_table_privilege('cuevo_api','app.portfolio_reviews','select'),'new disclosure does not expose raw portfolio review table');
select ok(not has_function_privilege('authenticated','internal.read_portfolio_source_work(uuid,uuid)','execute'),'browser role cannot invoke protected answer helper');
select ok(not has_function_privilege('cuevo_worker','internal.read_portfolio_source_work(uuid,uuid)','execute'),'worker cannot retrieve selected answer text');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.portfolio_command('reflection',(select item from selected_text),'{"expectedRevision":1,"title":"Private second revision","reflection":"Unreviewed later reflection"}','selected-text-reflection',repeat('d',64),'selected-text')is not null as revised;
reset role;update selected_text set new_revision=(select revision_id from app.portfolio_current where item_id=selected_text.item);set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select new_revision from selected_text))$$,'42501',null,'new reflection cannot inherit source publication');
select lives_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'previous exact parent revision remains available while new reflection awaits review');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select internal.portfolio_command('revoke',(select item from selected_text),'{"reason":"School revoked source sharing"}','selected-text-revoke',repeat('e',64),'selected-text')is not null as revoked;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_portfolio_source_work((select item from selected_text),(select revision from selected_text))$$,'42501',null,'parent pointer revocation immediately denies answer disclosure');
reset role;select is((select count(*)from app.portfolio_reviews where item_id=(select item from selected_text)),1::bigint,'source review remains immutable after reflection and revoke');
select*from finish();rollback;
